'use strict';
const DATA=window.REALM_DATA,defs=Object.fromEntries(DATA.items.map(d=>[d.id,d]));
const CLASS_RULES={
rogue:{hp:95,title:'Shadowstep',desc:'A quick, evasive duelist who rewards rapid weapon attacks.',rule:'Every 4 weapon activations: gain 1 dodge and deal 12 bonus damage.',event:'attack',threshold:4,proc:'rogue'},
archer:{hp:100,title:'Deadeye',desc:'Bow hits build precision; nearby quivers empower the finishing shot.',rule:'Every 4 bow activations: deal a precision shot for 40% of that bow’s primary damage, or 75% with an adjacent quiver.',event:'bow',threshold:4,proc:'archer'},
wizard:{hp:100,title:'Arcane Echo',desc:'Mana spending charges a repeat of your next offensive spell.',rule:'Every 5 mana spent: ready one echo. The next damaging ability repeats 80% of its primary damage. Echoes cannot trigger echoes; stores one.',event:'mana',threshold:5,proc:'wizard'},
priest:{hp:105,title:'Benediction',desc:'Healing also protects you and punishes your opponent.',rule:'Every 20 actual health restored: gain 10 block and deal 14 holy damage.',event:'heal',threshold:20,proc:'priest'},
warrior:{hp:115,title:'Battle Fury',desc:'Sustained weapon attacks build a controlled burst of fury.',rule:'Every 3 weapon activations: gain one Fury stack (+8% weapon primary damage, max 5). Refreshes a 10-second timer; Fury expires when it runs out.',event:'attack',threshold:3,proc:'warrior'},
knight:{hp:130,title:'Retribution',desc:'Heavy armor and shields turn enemy attacks against them.',rule:'Every 25 damage blocked: bash the enemy for 18 damage and gain 4 block.',event:'block',threshold:25,proc:'knight'},
paladin:{hp:120,title:'Sacred Oath',desc:'Sustain yourself while building a wall of sacred protection.',rule:'Every 4 seconds: heal 5 health and gain 7 block.',event:'time',threshold:4,proc:'paladin'},
assassin:{hp:100,title:'Toxic Edge',desc:'Fast weapons apply poison; poisoned enemies become increasingly vulnerable.',rule:'Every 3 weapon activations: apply 5 poison and 3 seconds of vulnerability.',event:'attack',threshold:3,proc:'assassin'},
necromancer:{hp:100,title:'Soul Harvest',desc:'Convert spent mana into life-draining attacks and undead allies.',rule:'Every 5 mana spent: drain 14 health and summon a skeleton with 3 damage per second.',event:'mana',threshold:5,proc:'necromancer'},
huntress:{hp:105,title:'Predator’s Mark',desc:'Traps and repeated attacks tear apart an afflicted opponent.',rule:'Every 4 weapon activations: apply 5 bleed and 4 seconds of weakness.',event:'attack',threshold:4,proc:'huntress'},
mystic:{hp:100,title:'Time Fracture',desc:'Manipulate enemy timing to create space for slower, stronger equipment.',rule:'Every 5 mana spent: delay the next enemy attack by up to 1.5 seconds and deal 15 damage. All delays share a 2-second budget per 5 seconds.',event:'mana',threshold:5,proc:'mystic'},
trickster:{hp:95,title:'Mirror Dance',desc:'Illusions absorb dangerous attacks while your daggers keep moving.',rule:'Every 5 seconds: gain 1 dodge and a 3-damage illusion summon for 8 seconds.',event:'time',threshold:5,proc:'trickster'},
sorcerer:{hp:100,title:'Chain Surge',desc:'Mana-fed lightning leaves your enemy exposed to follow-up attacks.',rule:'Every 4 mana spent: deal 20 damage and apply vulnerability for 4 seconds.',event:'mana',threshold:4,proc:'sorcerer'},
ninja:{hp:95,title:'Flowing Steel',desc:'Quick katana attacks fuel an escalating burst of damage.',rule:'Every 4 weapon activations: deal 16 damage and recover 2 mana.',event:'attack',threshold:4,proc:'ninja'},
samurai:{hp:115,title:'Focused Draw',desc:'Weapon attacks prepare an empowered wakizashi strike.',rule:'Every 3 weapon activations: gain 1 Focus (max 3). Your next wakizashi consumes all Focus for +40% primary damage per stack.',event:'attack',threshold:3,proc:'samurai'},
bard:{hp:105,title:'Inspiring Rhythm',desc:'Hasted equipment turns activations into supporting music.',rule:'Hasted item activations build Rhythm, at most once per second. Every 3 Rhythm: restore 2 mana and gain 6 block. Lutes grant local haste.',event:'rhythm',threshold:3,proc:'bard'},
summoner:{hp:100,title:'Pact of Many',desc:'Spend mana to build a growing army of temporary companions.',rule:'Every 5 mana spent: summon a companion that deals 5 damage per second for 10 seconds and gain 6 block.',event:'mana',threshold:5,proc:'summoner'},
kensei:{hp:110,title:'Resolute Dash',desc:'Evasive movement turns incoming danger into a counterattack.',rule:'Whenever you dodge: deal 16 damage and gain 6 block. Also gain 1 dodge every 8 seconds.',event:'dodge',threshold:1,proc:'kensei'},
druid:{hp:105,title:'Wild Communion',desc:'Healing nurtures a companion and reinforces your defenses.',rule:'Every 18 actual health restored: summon a 4-damage spirit for 10 seconds and gain 6 block.',event:'heal',threshold:18,proc:'druid'}
};
const classes=Object.fromEntries(DATA.classes.map(c=>[c.id,{...c,...CLASS_RULES[c.id]}]));
let ROOMS=[];
const $=id=>document.getElementById(id),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let s=null,selected=null,uid=0,timer=null,speed=1,logs=[],stock=[],reward=[],toastTimer,catalogueState={search:'',group:'',classId:'',variant:'',mechanic:'',page:0},catalogueOpen=false,returnModal=null,modalKind='',dragId=null;
function isOffClass(d,classId=s?.classId){return !!classId&&d.group!=='ring'&&d.group!=='consumable'&&Array.isArray(d.classes)&&d.classes.length>0&&d.classes.length<Object.keys(classes).length&&!d.classes.includes(classId)}
function itemManaCost(d,i=null){if(i)return enchantManaCost(d,i);return (d.mana||0)+(isOffClass(d)&&d.group==='ability'?1:0)}
function affinityCooldown(d){return d.cd*(isOffClass(d)?1.5:1)}
function affinityNote(d){const native=Array.isArray(d.classes)?d.classes:[];if(d.group==='ring'||d.group==='consumable'||!native.length||native.length===Object.keys(classes).length)return '';const names=native.map(id=>classes[id]?.name||id).join(', ');return `<div class="affinity-note ${isOffClass(d)?'offclass':''}"><b>${isOffClass(d)?'⚠ OFF-CLASS EQUIPMENT':'✓ CLASS COMPATIBLE'}</b><p>Native classes: ${esc(names)}.</p>${isOffClass(d)?`<p>Cooldown +50%: ${d.cd}s → ${affinityCooldown(d).toFixed(2)}s.${d.group==='ability'?` Mana +1: ${d.mana} → ${itemManaCost(d)}.`:''}</p>`:'<p>No off-class penalty.</p>'}</div>`}
function art(id,cls=''){const d=defs[id];return spriteMarkup(d.sprite,d.name,`itempixel ${cls} ${d.isShiny?'shiny-sprite':''}`)}
function dims(i){const d=defs[i.type];return i.rot?[d.h,d.w]:[d.w,d.h]}
function occupied(i){const [w,h]=dims(i);return Array.from({length:w*h},(_,n)=>[i.x+n%w,i.y+Math.floor(n/w)])}
function fits(i,x,y,rot=i.rot){if(!Number.isInteger(x)||!Number.isInteger(y))return false;const [w,h]=dims({...i,rot});return x>=0&&y>=0&&x+w<=6&&y+h<=5&&!s.items.some(j=>j.id!==i.id&&occupied(j).some(([a,b])=>a>=x&&a<x+w&&b>=y&&b<y+h))}
function adjacent(a,b){return occupied(a).some(([x,y])=>occupied(b).some(([u,v])=>Math.abs(x-u)+Math.abs(y-v)===1))}
function makeItem(type){return initDaggerEnchantments({id:++uid,type,x:null,y:null,rot:false,charge:0,activations:0,used:false,quantity:1,usesSpent:0})}
function autoPlace(i){for(const rot of [false,true])for(let y=0;y<5;y++)for(let x=0;x<6;x++)if(fits(i,x,y,rot)){Object.assign(i,{x,y,rot});s.items.push(i);return true}return false}
function rng(){s.seed=(Math.imul(1664525,s.seed)+1013904223)>>>0;return s.seed/4294967296}
function log(t){logs.unshift(t);logs=logs.slice(0,70);if(!window.__TEST__)$('log').innerHTML=logs.map(v=>`<div>${esc(v)}</div>`).join('')}
function toast(t){if(window.__TEST__)return;$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2900)}
function flash(id){if(window.__TEST__)return;const e=$(id);if(!e)return;e.classList.add('flash');setTimeout(()=>e.classList.remove('flash'),160)}
function passive(event,amount){if(!amount||s.phase!=='fight')return;const c=classes[s.classId];if(c.event!==event)return;s.progress+=amount;let guard=0;while(s.progress>=c.threshold&&guard++<50){s.progress-=c.threshold;switch(c.proc){case'rogue':s.dodge=Math.min(3,s.dodge+1);hit(12);break;case'archer':s.precisionReady=true;break;case'wizard':s.arcaneEchoReady=true;break;case'priest':gainBlock(10);hit(14);break;case'warrior':s.fury=Math.min(5,(s.fury||0)+1);s.furyTime=10;break;case'knight':hit(18);gainBlock(4);break;case'paladin':restore(5,false);gainBlock(7);break;case'assassin':apply('poison',5);apply('vulnerable',3);break;case'necromancer':hit(14);restore(7,false);summon(3,10);break;case'huntress':apply('bleed',5);apply('weaken',4);break;case'mystic':delayEnemyAttack(1.5);hit(15);break;case'trickster':s.dodge=Math.min(3,s.dodge+1);summon(3,8);break;case'sorcerer':hit(20);apply('vulnerable',4);break;case'ninja':hit(16);s.mana=Math.min(50,s.mana+2);break;case'samurai':s.focus=Math.min(3,(s.focus||0)+1);break;case'bard':s.mana=Math.min(50,s.mana+2);gainBlock(6);break;case'summoner':summon(5,10);gainBlock(6);break;case'kensei':hit(16);gainBlock(6);break;case'druid':summon(4,10);gainBlock(6);break}log('✦ '+c.title+' activates.');flash('playerSprite')}}
function summon(power,duration){if(s.summons.length<8)s.summons.push({power,duration});else s.summons[0].duration=Math.max(s.summons[0].duration,duration)}
function apply(effect,amount,source=null){const e=s.enemy;switch(effect){case'damage':return hit(amount+s.power);case'drain':{const dealt=hit(amount+s.power);restore(Math.ceil(dealt*.4));return dealt}case'heal':return restore(amount);case'block':gainBlock(amount);break;case'mana':s.mana=Math.min(50,s.mana+amount);break;case'burn':e.burn=Math.min(80,e.burn+amount);break;case'poison':e.poison=Math.min(24,e.poison+amount);e.poisonTime=10;break;case'bleed':e.bleed=Math.min(24,e.bleed+amount);e.bleedTime=6;break;case'chill':case'weaken':case'vulnerable':e[effect]=Math.min(15,e[effect]+amount);break;case'haste':grantItemHaste(source,amount);break;case'summon':summon(amount,8);break;case'thorns':s.thorns=Math.min(35,s.thorns+amount);break;case'dodge':s.dodge=Math.min(3,s.dodge+amount);break;case'charge':s.power=Math.min(40,s.power+amount);break}}
function effectText(effect,n){return ({damage:`Deal ${n} damage`,drain:`Deal ${n} damage and heal for 40% dealt`,heal:`Restore ${n} health`,block:`Gain ${n} block`,mana:`Generate ${n} mana`,burn:`Apply ${n} burning (ticks each second; decays)`,poison:`Apply ${n} poison (ticks for 10s; decays 1 stack/s; max 24)`,bleed:`Apply ${n} bleed (ticks for 6s; decays 1 stack/s; max 24)`,chill:`Chill for ${n}s (enemy attacks 35% slower)`,weaken:`Weaken for ${n}s (enemy deals 25% less damage)`,vulnerable:`Expose for ${n}s (enemy takes 25% more damage)`,haste:`Grant adjacent items ${Math.min(15,n)}s of haste (+25% recharge; shared edges only, excludes self; refreshes, does not stack)`,summon:`Summon a ${n}-damage companion for 8s (attacks each second)`,thorns:`Gain ${n} thorns (reflect on each enemy attack)`,dodge:`Gain ${n} dodge charge${n===1?'':'s'} (avoid an attack)`,charge:`Gain +${n} damage power for this battle`})[effect]||effect}
function describe(d){if(d.daggerUpdate&&d.mechanic.perShot)return `Fire ${d.mechanic.shots} shots for ${d.amount} base damage each (${d.amount*d.mechanic.shots} total before misses).`;if(d.mechanic?.regen)return `Restore ${d.amount} health over ${d.mechanic.regen}s. Strongest mushroom only; healing fatigue applies.`;if(d.mechanic)return `${effectText(d.effect,d.amount)}.${d.mechanic.keepAffix&&d.affix?' '+effectText(d.affix,d.affixAmount)+'.':''}${d.once?' Stackable to 5; one use per copy per battle.':''}${healingConsumableNote(d)}`;return `${effectText(d.effect,d.amount)}.${d.affix?' '+effectText(d.affix,d.affixAmount)+'.':''}${d.once?' Stackable to 5; one use per copy per battle.':''}${healingConsumableNote(d)}`}
function conditionActive(i){const d=defs[i.type],others=s.items.filter(j=>j.id!==i.id);switch(d.condition){case'adjacent weapon':return others.some(j=>defs[j.type].group==='weapon'&&adjacent(i,j));case'adjacent ability':return others.some(j=>defs[j.type].group==='ability'&&adjacent(i,j));case'adjacent ring':return others.some(j=>defs[j.type].group==='ring'&&adjacent(i,j));case'same-row ally':return others.some(j=>j.y===i.y);case'every third activation':return (i.activations+1)%3===0;case'below half health':return s.hp<s.max/2;case'above half mana':return s.mana>=10;case'while shielded':return s.block>0;case'while enemy afflicted':return s.enemy.burn+s.enemy.poison+s.enemy.bleed+s.enemy.chill+s.enemy.weaken+s.enemy.vulnerable>0;case'first activation':return i.activations===0;default:return false}}
function activate(i){if(!healingConsumableReady(i))return false;const d=defs[i.type];if(d.mechanic)return activateSignature(i);const manaCost=itemManaCost(d,i);if(manaCost>s.mana||i.used)return false;const boosted=conditionActive(i);s.mana-=manaCost;passive('mana',manaCost);i.activations++;i.charge=0;consumeStackUse(i);const primary=classPrimaryAmount(i,enchantPrimary(i,d.amount));apply(d.effect,primary,i);if(d.affix)apply(d.affix,d.affixAmount,i);if(boosted){if(['damage','drain','block','heal'].includes(d.effect))apply(d.effect,d.bonus,i);else hit(d.bonus);log('✧ '+d.name+' synergy: +'+d.bonus+(['damage','drain','block','heal'].includes(d.effect)?' '+d.effect:' damage')+'.')}if(d.group==='weapon'){passive('attack',1);itemEvent('weapon',1,i)}else if(d.group==='ability')itemEvent('ability',1,i);triggerEnchantments(i);classActivation(i,primary);itemFxActivation(i,boosted);s.lastItemEffect={itemId:i.id,effect:d.effect,amount:primary};log(d.name+': '+effectText(d.effect,d.amount)+'.');flash('item'+i.id);return true}
function enterRest(){daggerNoncombatBonus();s.phase='rest';save();showRest()}
function enterShop(){return enterSpecialistShop()}
function buy(id){if(s.phase!=='shop'||!stock.includes(id))return;if(!daggerAvailable(id))return toast('This item is currently unavailable.');const d=defs[id];if(s.gold<d.price)return toast('Not enough gold.');if(!receiveItem(makeItem(id)))return;s.gold-=d.price;stock=stock.filter(t=>t!==id);save();render();showShop()}
function buyHeal(){if(s.phase!=='shop')return;if((s.shopHeals||0)>=1)return toast('The trader has no healing draughts left.');if(s.gold<25)return toast('You need 25 gold.');if(s.hp>=s.max)return toast('Already at full health.');s.gold-=25;s.shopHeals=(s.shopHeals||0)+1;restore(25,false);save();render();showShop()}
function leaveShop(){if(s.phase==='shop')nextRoom()}
function primary(){if(['won','lost'].includes(s.phase))chooseClass();else if(s.phase==='prep')startFight();else restorePhaseModal()}
let inspected=null;
function findInspected(){return [...s.items,...s.stash].find(i=>i.id===inspected)||findSelected()}
function findSelected(){return [...s.items,...s.stash].find(i=>i.id===selected)}
function place(x,y){if(s.phase!=='prep')return toast('Rearrange your backpack between battles.');const i=findSelected();if(!i)return toast('Select an item first.');const merge=stackAtCell(i,x,y);if(merge&&mergeStacks(i,merge))return;if(!fits(i,x,y))return toast('That item does not fit. Try rotating it or clearing space.');s.stash=s.stash.filter(j=>j.id!==i.id);if(!s.items.includes(i))s.items.push(i);Object.assign(i,{x,y});render();save()}
function rotateSelected(){inventoryRotate()}
function stashSelected(){if(s.phase!=='prep')return;const i=findSelected();if(!i||!s.items.includes(i))return;if(!stashCanReceive(i,false))return toast(STASH_FULL_MESSAGE);s.items=s.items.filter(j=>j.id!==i.id);Object.assign(i,{x:null,y:null});receiveItem(i,false);render();save()}
function discardSelected(id=selected){if(s.phase!=='prep')return;const i=[...s.items,...s.stash].find(i=>i.id===id);if(!i)return;modal('Discard '+defs[i.type].name+'?','This removes the entire selected stack or item from your current run.',`<button onclick="closeModal(true)">Keep item</button> <button class="gold" onclick="removeItem(${i.id})">Discard item</button>`,'confirm')}
function removeItem(id){s.items=s.items.filter(i=>i.id!==id);s.stash=s.stash.filter(i=>i.id!==id);selected=null;closeModal(true);render();save()}
function selectItem(id){const i=[...s.items,...s.stash].find(i=>i.id===id);if(!i)return;inspected=id;const deselect=selected===id;inventoryIntent=null;inventoryClearPreview();selected=deselect?null:id;if(!deselect&&s.phase==='prep')inventoryPick(i);render()}
function cycleSpeed(){speed=speed===1?2:speed===2?4:1;$('speed').textContent=speed+'×'}
function modal(title,desc,body,kind='normal'){if(window.__TEST__)return;modalKind=kind;$('overlay').innerHTML=`<div class="overlay"><div class="modal ${kind==='catalogue'?'catalogue-modal':kind==='classes'?'classes-modal':kind==='reward'?'reward-modal':kind==='rewardinspect'?'reward-inspect-modal':kind==='shop'?'shop-modal':kind==='shopinspect'?'shop-inspect-modal':kind==='trade'?'event-trade-modal':''}"><div class="eyebrow">REALMPACK · THE SHATTERED VAULT</div><h1>${title}</h1><p>${desc}</p>${body}</div></div>`}
function confirmRestart(){if(s?.phase==='fight')return toast('Finish the battle before changing characters.');modal('Begin a fresh descent?','Your current run will be replaced after you select a character.',`<button onclick="closeModal()">Keep playing</button> <button class="gold" onclick="chooseClass()">Choose character</button>`,'confirm')}
function itemCard(id,action){const d=defs[id];return `<button class="choice ${d.isShiny?'shiny':''}" onclick="${action}"><div class="ico">${art(id)}</div><b>${esc(d.name)}</b><small style="color:${d.color}">${d.rarity} · ${esc(d.tier)} · ${esc(d.kind)} · ${d.w}×${d.h}</small><p>${esc(describe(d))}</p>${shinyInfo(d)}${affinityNote(d)}${adjacencyGuide(d)}<small>◷ ${affinityCooldown(d).toFixed(2)}s${itemManaCost(d)?' · ✦ '+itemManaCost(d)+' mana':''}</small>${d.mechanic?mechanicCard(d):d.bonus?`<p class="synergy">${esc(d.condition)}: +${d.bonus} ${['damage','drain','block','heal'].includes(d.effect)?d.effect:'damage'}</p>`:''}</button>`}
function rewardCard(id,context='reward'){const shop=context==='shop',inspect=shop?'inspectShop':'inspectReward',take=shop?'buy':'takeLoot',d=defs[id],off=isOffClass(d),room=stashCanReceive({id:-1,type:id}),primary=effectText(d.effect,d.amount).replace(/\s*\([^)]*\)/g,'');return `<article class="loot-card ${d.isShiny?'shiny':''}"><div class="loot-heading">${art(id)}<div><h2>${esc(d.name)}</h2><small style="color:${d.color}">${esc(d.rarity)} · ${esc(d.tier)} · ${esc(d.kind)}${d.isShiny?' · Shiny':''}</small></div></div><div class="loot-stats"><span>${d.w}×${d.h}</span><span>◷ ${affinityCooldown(d).toFixed(2)}s${itemManaCost(d)?' · ✦ '+itemManaCost(d)+' mana':''}</span></div><p class="loot-primary">${esc(primary)}</p>${off?'<small class="loot-affinity">⚠ Off-class: +50% cooldown'+(d.group==='ability'?', +1 mana':'')+'</small>':'<small class="loot-affinity compatible">✓ Class compatible</small>'}<div class="loot-actions"><button onclick="${inspect}('${id}')" aria-label="Inspect ${esc(d.name)}">Inspect</button><button class="gold" title="${room?'':STASH_FULL_MESSAGE}" ${!room||shop&&s.gold<d.price?'disabled':''} onclick="${take}('${id}')" aria-label="${shop?'Buy':'Take'} ${esc(d.name)}">${shop?'Buy · '+d.price+'g':'Take item'}</button></div></article>`}
function inspectReward(id){if(s.phase!=='reward'||!reward.includes(id))return;modal(defs[id].name,'Full effects and class compatibility. You can return without choosing.',`<div class="loot-inspect-content">${itemCard(id,`takeLoot('${id}')`).replace(/^<button/,'<div').replace(/ onclick="[^"]*"/,'').replace(/<\/button>$/,'</div>')}</div><div class="loot-inspect-footer"><button onclick="showRewards()">← Back to all loot</button> <button class="gold" onclick="takeLoot('${id}')">Take this item</button></div>`,'rewardinspect')}
function showRewards(){modal('Victory. Choose your spoils.',reward.some(id=>defs[id].isShiny)?'✦ A very rare Shiny appeared! Take one item for your stash.':'Take one item for your stash. Inspect any item for its complete effects.',`<div class="loot-grid" style="--loot-count:${Math.min(4,Math.max(1,reward.length))}">${reward.map(rewardCard).join('')}</div><div class="loot-footer"><span>Choose one · All other items are left behind</span><button onclick="takeLoot(null)">Leave loot · recover ${Math.max(6,Math.round(s.max*.06))} health</button></div>`,'reward')}
function inspectShop(id){if(s.phase!=='shop'||!stock.includes(id))return;const d=defs[id];modal(d.name,'Inspect this offer. Your gold is only spent when you buy.',`<div class="shop-inspect-summary">${art(id)}<div><p>${esc(describe(d))}</p><small>${d.w}×${d.h} · ${affinityCooldown(d).toFixed(2)}s · ${itemManaCost(d)} mana</small></div></div><div class="shop-inspect-sections">${affinityNote(d)}${d.mechanic?mechanicCard(d):d.bonus?`<p class="synergy">${esc(d.condition)}: +${d.bonus} ${['damage','drain','block','heal'].includes(d.effect)?d.effect:'damage'}.</p>`:''}${adjacencyGuide(d)}${shinyInfo(d)}</div><div class="shop-footer"><button onclick="showShop()">← Back to shop</button><button class="gold" ${s.gold<d.price?'disabled':''} onclick="buy('${id}')">Buy · ${d.price} gold</button></div>`,'shopinspect')}
function showShop(){if(s.phase!=='shop')return;const unavailable=(s.shopHeals||0)>=1||s.gold<25||s.hp>=s.max,m=currentShopSpecialist();modal(m?.name||'The wandering trader',`${s.gold} gold · ${shopSpecialistNote(m)}`, `<div class="shop-banner">${m?specialistShopScene({shopKind:m.kind}):eventScene('shop')}</div><div class="shop-offers" style="--shop-count:${Math.max(1,stock.length)}">${stock.map(id=>rewardCard(id,'shop')).join('')||'<p class="shop-empty">All offers purchased.</p>'}</div><div class="shop-footer"><button ${unavailable?'disabled':''} onclick="buyHeal()">${(s.shopHeals||0)>=1?'Healing sold out':'Heal 25 HP · 25g'}</button><button class="gold" onclick="leaveShop()">Continue descent ↗</button></div>`,'shop')}

function showHelp(){modal('Build your backpack. Let it battle.','Combat pauses while this guide or the catalogue is open.',`<div class="help-copy"><p><b>Arrange:</b> drag from any cell of an item; its grabbed cell stays under your pointer. Green previews fit, red previews are blocked. Press R while dragging to rotate, and Escape to cancel. You can also select an item and click its destination. Drop onto the stash to unpack it. Only packed items activate.</p><p><b>Synergies:</b> tiered items keep a consistent family role, and higher tiers improve output or efficiency. Special items can add a themed effect or signature. Ten additional adjacency rules reward combinations of weapons, armor, rings, mana, healing, and afflictions. Inspect each item for its rules. Only edge contact counts; stacks count as one neighbor. Primary adjacency bonuses cap at +35%. Bows also recharge 15% faster per adjacent quiver (up to 60%). Mana regenerates by 1 each second; mana-starved items wait at full charge.</p><p><b>Dungeon tiers:</b> skull markers show Beginner (1), Standard (2), Advanced (3), Exaltation (4), and Apex Exalt (5). Tiers are custom to RealmPack. Compare at equal depth and run mode; tougher dungeons grant more gold.</p><p><b>Pressure:</b> Block caps at 60% of maximum health and loses 10% each second. Dodge cannot avoid two consecutive strikes. Combat healing weakens after 20 seconds, to a minimum of 50%. Enemy damage ramps up after 30 seconds. Bosses pierce some block and resist affliction damage.</p><p><b>Combat:</b> cooldown bars fill automatically. Colored statuses show burning, poison, bleed, chill, and vulnerability. Every class has a working passive shown beside the map.</p><p><b>Specialist shops:</b> each weapon, ability and armor family has its own merchant; rings and consumables have separate shops. New shops favor native equipment (70%) and shared supplies (25%), with 5% off-class specialists. Each merchant stocks only its own type. Shop identity and offers stay fixed after entering or reloading.</p><p><b>Loot:</b> rewards favor your class’s equipment. All classes can use any equipment, but class-restricted items have 50% longer cooldowns off-class, and off-class abilities cost 1 extra mana. Shared native weapon/armor families work normally for their compatible classes. Rings and consumables have no off-class penalty. The stash holds nine item slots. Identical single-use items stack up to five copies in one slot. Each copy activates once per battle, one cooldown at a time, and all copies refresh next battle. New copies merge automatically; drag one matching stack onto another to combine, or use Split one into stash in inspection.</p><p><b>Catalogue:</b> search ${DATA.items.length.toLocaleString()} imported items. Start a Sandbox from character selection to add any item freely. Normal runs earn their equipment. Signature effects replace generic secondary bonuses on upgraded items. Search the catalogue by mechanic name, or use its mechanic filter. The expedition has three acts of ten rooms, followed by optional endless acts. Choose portals and paths; elite enemies and bosses drop better loot. Bosses grant permanent run blessings.</p><p><b>Source:</b> names and sprites are from realm.wiki. Shapes, cooldowns and effects are custom adaptations. Poison and bleed cap at 24 stacks and lose one stack per second. Tiered equipment follows consistent family progression. Special equipment uses themed family bonuses or curated iconic mechanics.</p></div><button class="gold" onclick="closeModal()">Return to the vault</button>`,'help')}
function openCatalogue(){catalogueOpen=true;catalogueState.page=0;drawCatalogue()}
function catalogueFilter(key,value){catalogueState[key]=value;catalogueState.page=0;drawCatalogue(true,key)}
function drawCatalogue(preserveFocus=false,focusKey=''){const q=catalogueState,filtered=DATA.items.filter(d=>!d.catalogueHidden&&(!q.search||(d.name+' '+(d.mechanic?.title||'')+' '+(d.mechanic?.text||'')).toLowerCase().includes(q.search.toLowerCase()))&&(!q.group||d.group===q.group)&&(!q.classId||d.classes.includes(q.classId))&&(!q.variant||(q.variant==='shiny'?d.isShiny:!d.isShiny))&&(!q.mechanic||d.mechanic?.key===q.mechanic)),pages=Math.max(1,Math.ceil(filtered.length/18));q.page=Math.min(q.page,pages-1);const current=filtered.slice(q.page*18,(q.page+1)*18);modal('The item compendium',`${DATA.items.filter(d=>!d.catalogueHidden).length.toLocaleString()} sprite-backed items · ${Object.keys(classes).length} playable classes · ${DATA.stats.mechanicTypes} signature mechanics`, `<div class="catalogue-controls"><input id="catalogueSearch" aria-label="Search items" placeholder="Search item names…" value="${esc(q.search)}" oninput="catalogueFilter('search',this.value)"><select aria-label="Filter item type" onchange="catalogueFilter('group',this.value)"><option value="">All item types</option>${['weapon','ability','armor','ring','consumable'].map(g=>`<option value="${g}" ${q.group===g?'selected':''}>${g}</option>`).join('')}</select><select aria-label="Filter class" onchange="catalogueFilter('classId',this.value)"><option value="">All classes</option>${Object.values(classes).map(c=>`<option value="${c.id}" ${q.classId===c.id?'selected':''}>${c.name}</option>`).join('')}</select><select aria-label="Filter item versions" onchange="catalogueFilter('variant',this.value)"><option value="">All versions</option><option value="regular" ${q.variant==='regular'?'selected':''}>Regular only</option><option value="shiny" ${q.variant==='shiny'?'selected':''}>Shiny only (${DATA.stats.shinyItems})</option></select><select aria-label="Filter signature mechanic" onchange="catalogueFilter('mechanic',this.value)"><option value="">All mechanics</option>${[...new Map(DATA.items.filter(d=>d.mechanic).map(d=>[d.mechanic.key,d.mechanic.title])).entries()].sort((a,b)=>a[1].localeCompare(b[1])).map(([key,title])=>`<option value="${key}" ${q.mechanic===key?'selected':''}>${esc(title)}</option>`).join('')}</select><button onclick="closeCatalogue()">Close ✕</button></div><div class="catalogue-note">${s?.practice?'SANDBOX · Add any item to your stash between battles.':'Inspect any item here. To test items freely, start a Sandbox from character selection.'} ${s?.practice&&s.phase!=='prep'?'Finish the room before adding items.':''}</div><div class="catalogue-grid">${current.map(d=>`<article class="codex-card ${d.isShiny?'shiny':''}"><div class="codex-top">${art(d.id)}<div><h3>${esc(d.name)}</h3><small style="color:${d.color}">${d.rarity} · ${esc(d.tier)} · ${esc(d.kind)}</small></div></div><p>${esc(describe(d))}</p>${shinyInfo(d)}${affinityNote(d)}${adjacencyGuide(d)}<div class="label">${d.w}×${d.h} · ${affinityCooldown(d).toFixed(2)}s · ${itemManaCost(d)} mana</div>${d.mechanic?mechanicCard(d):d.bonus?`<p class="synergy">${esc(d.condition)}: +${d.bonus} ${['damage','drain','block','heal'].includes(d.effect)?d.effect:'damage'}.</p>`:''}<div class="codex-bottom"><a href="${d.source}" target="_blank" rel="noopener">Wiki ↗</a>${s?.practice?`<button ${s.phase!=='prep'||!daggerAvailable(d.id)?'disabled':''} onclick="addSandbox('${d.id}')">${daggerAvailable(d.id)?'+ Stash':'Unavailable'}</button>`:''}</div></article>`).join('')||'<p>No matching items. Try a different search.</p>'}</div><div class="pagination"><button ${q.page===0?'disabled':''} onclick="cataloguePage(-1)">← Previous</button><small>${filtered.length.toLocaleString()} matches · Page ${q.page+1} / ${pages}</small><button ${q.page===pages-1?'disabled':''} onclick="cataloguePage(1)">Next →</button></div><small>Generated adaptations with item-specific timing, effects, and synergy conditions; selected iconic items are hand-tuned.</small>`,'catalogue');if(preserveFocus&&focusKey==='search'){const input=$('catalogueSearch');input.focus();input.setSelectionRange(input.value.length,input.value.length)}}
function cataloguePage(delta){catalogueState.page+=delta;drawCatalogue()}
function closeCatalogue(){catalogueOpen=false;restorePhaseModal()}
function addSandbox(id){if(!s.practice||s.phase!=='prep'||!daggerAvailable(id))return;if(!receiveItem(makeItem(id)))return;save();render();toast(defs[id].name+' added to your stash.')}
function render(){if(window.__TEST__)return;if(!s)return;const r=ROOMS[s.room],c=classes[s.classId];$('roomtitle').textContent=r.name;$('roomtype').textContent=`ROOM ${String(s.room+1).padStart(2,'0')} / 07`;$('ename').textContent=r.enemy;if(!r.sprite){$('enemySprite').textContent=r.icon;$('enemySprite').dataset.sprite='';}setBattleSprite('playerSprite',c.sprite,c.name);$('playerName').textContent=c.name;updateClassPanel(c);$('status').textContent=(s.practice?'SANDBOX · ':'')+(s.phase==='fight'?'● Battle in progress':s.phase==='prep'?'● Preparing for battle':s.phase==='won'?'✦ Vault conquered':s.phase==='lost'?'Run ended':'● Choose your next step');$('phase').textContent=s.phase==='fight'?'EQUIPMENT ACTIVATING AUTOMATICALLY':s.phase==='prep'?(r.type==='event'?'NON-COMBAT ENCOUNTER':'PREPARE YOUR LOADOUT'):s.phase.toUpperCase();$('fight').disabled=s.phase==='fight';$('fight').textContent=s.phase==='fight'?'Fighting…':['won','lost'].includes(s.phase)?'New run ↻':s.phase!=='prep'?'Continue ↗':['shop','rest','event'].includes(r.type)?'Enter room ↗':'Begin battle ↗';$('capacity').textContent=s.items.reduce((a,i)=>{const [w,h]=dims(i);return a+w*h},0)+' / 30 CELLS';renderBackpack();renderDetail();updateStats()}
function renderDetail(){const i=findInspected();if(!i){$('detail').innerHTML='<p>Hover, focus or select an item to inspect its effects and synergy. Explore the catalogue to see the full collection.</p>';return}const d=defs[i.type],[w,h]=dims(i);$('detail').innerHTML=`<div class="label" style="color:${d.color}">${d.rarity} · ${esc(d.tier)} · ${esc(d.kind)}</div><div class="detailtitle"><span>${art(i.type)}</span><h2>${esc(d.name)}</h2></div><div class="stats"><span>▦ ${w}×${h}</span><span>◷ ${cooldown(i).toFixed(2)}s</span><span>✦ ${itemManaCost(d,i)} mana</span></div><p>${esc(describe(d))}</p>${shinyInfo(d)}${affinityNote(d)}${d.mechanic?mechanicCard(d):d.bonus?`<p class="synergy">${esc(d.condition)}: +${d.bonus} ${['damage','drain','block','heal'].includes(d.effect)?d.effect:'damage'}.</p>`:''}${infusionMarkup(i)}${stackDetail(i)}${adjacencyGuide(d)}${enchantMarkup(i)}${itemEffectsDetail(i)}${i.eventHaste?`<p class="synergy">Tempered this run: ${Math.round(i.eventHaste*100)}% shorter cooldown.</p>`:''}<div class="label" id="signatureMeter"></div><small>${s.items.includes(i)?'Packed and active':'Stashed and inactive'} · ${d.once?'One use per copy per battle':'Repeats automatically'}</small><div style="margin-top:12px"><button onclick="discardSelected(${i.id})" style="padding:6px 10px">Discard</button> <a href="${d.source}" target="_blank" rel="noopener">Wiki ↗</a></div>`}
function updateStats(){if(window.__TEST__||!s)return;const e=s.enemy;$('php').style.width=100*s.hp/s.max+'%';$('ehp').style.width=(e.max?100*e.hp/e.max:100)+'%';$('pstats').textContent=Math.ceil(s.hp)+' / '+s.max+' HP';$('estats').textContent=e.max?Math.ceil(e.hp)+' / '+e.max+' HP · '+e.damage+' dmg / '+e.cd+'s':'A moment of respite';$('mana').textContent='✦ '+s.mana+' mana';$('block').textContent='⬡ '+s.block+' block';$('gold').textContent='◈ '+s.gold+' gold';$('clock').textContent=String(Math.floor(s.time/60)).padStart(2,'0')+':'+String(Math.floor(s.time%60)).padStart(2,'0');const active=[e.burn?'🔥 '+e.burn+' burn':'',e.poison?'☠ '+e.poison+' poison':'',e.bleed?'🩸 '+e.bleed+' bleed':'',e.chill>0?'❄ chilled':'',e.vulnerable>0?'◇ exposed':'',e.weaken>0?'↓ weakened':'',s.dodge?'◌ '+s.dodge+' dodge':'',s.summons.length?'✦ '+s.summons.length+' companions':'',s.haste>0?'↑ class haste':'',s.items.some(i=>(i.hasteRemaining||0)>0)?'↑ adjacent haste':'',s.time<(s.realmArmoredUntil||0)?'⬡ Armored · 20% reduction':'',s.time<(s.realmDivineUntil||0)?'✧ Divine protection ready':'',s.time<(s.daggerInvulnerableUntil||0)?'♥ Heartguard immunity':'',s.realmMushroom?'♧ healing mushroom':'',s.thorns?'♧ '+s.thorns+' thorns':'',s.power?'⚔ +'+s.power+' power':''].filter(Boolean);$('effects').textContent=active.join(' · ')||'No active effects';const c=classes[s.classId];$('passiveProgress').textContent=c.title+' · '+Math.floor(s.progress)+' / '+c.threshold+(classStateText()?' · '+classStateText():'');for(const i of s.items){const tile=$('item'+i.id);if(tile)updateStackBadge(tile,i);const el=$('cd'+i.id);if(el){el.style.width=(i.used?100:Math.min(100,i.charge/cooldown(i)*100))+'%';el.style.background=i.used?'#6d7666':defs[i.type].color}}const stackUses=$('stackUses'),stackItem=findInspected();if(stackUses&&stackItem)stackUses.textContent=s.phase==='fight'?stackRemaining(stackItem):stackCount(stackItem);updateExpeditionUI();updateItemEffects();const meter=$('signatureMeter'),item=findInspected();if(meter&&item&&defs[item.type].mechanic){const state=specialState(item);meter.textContent=defs[item.type].realmIdentity?realmStateText(item):`Activations: ${item.activations} · Stored: ${state.stored} · Combo: ${state.counter}`}}
/* The Realm Descent: generated routes and source-backed encounter adaptations. */
const ENCOUNTERS=window.ENCOUNTER_DATA,encounterDefs=Object.fromEntries(ENCOUNTERS.encounters.map(e=>[e.id,e])),dungeonDefs=Object.fromEntries(ENCOUNTERS.dungeons.map(d=>[d.id,d]));describeHexerTiming();
const DIFFICULTIES={story:{name:'Explorer',hp:.75,damage:.7,reward:.9,desc:'A gentler version of the rebalanced descent.'},normal:{name:'Adventurer',hp:1,damage:1,reward:1,desc:'Build upgrades are essential; elites and bosses punish weak defenses.'},veteran:{name:'Veteran',hp:1.35,damage:1.25,reward:1.15,desc:'Demanding enemies with higher pressure and gold rewards.'},nightmare:{name:'Exalted',hp:1.8,damage:1.55,reward:1.3,desc:'Severe pressure for carefully optimized builds.'}};
let selectedDifficulty='normal',bestiaryOpen=false,bestiarySearch='',bestiaryPage=0;
const FLOOR_TYPES=['combat','combat','event','combat','rest','elite','shop','combat','event','boss'];
function emptyRoute(from=0){return Array.from({length:30},(_,i)=>({name:'Uncharted chamber',enemy:'Choose your portal',icon:'◇',hp:0,damage:0,cd:3,type:FLOOR_TYPES[i%10],depth:from+i+1}))}
function pick(array){return array[Math.floor(rng()*array.length)]}
function actIndex(){return Math.floor(s.room/10)}
function difficulty(){return DIFFICULTIES[s.difficulty]||DIFFICULTIES.normal}
function goldReward(role,depth,risk=false,dungeonId=null){const tier=dungeonRating(dungeonId);return Math.round((14+Math.min(30,depth)*.4)*(role==='boss'?2.2:role==='elite'?1.5:1)*difficulty().reward*(risk?1.3:1)*(tier?.gold||1))}
function rebalanceGold(){const update=r=>{if(r?.encounterId)r.gold=goldReward(r.type,r.depth||s.room+1,r.risk,encounterDefs[r.encounterId]?.dungeon);return r};ROOMS.slice(s.room).forEach(update);(s.pathChoices||[]).forEach(update);for(const [depth,options] of Object.entries(s.mapBranches||{}))if(Number(depth)>=s.room)options.forEach(update)}
function scaledRoom(id,depth=s.room+1,risk=false,forcedRole=null){const d=encounterDefs[id],p=ENCOUNTERS.profiles[d.profile],role=forcedRole||d.role,diff=difficulty(),tier=dungeonRating(d.dungeon),cycle=Math.floor((depth-1)/30),floorScale=Math.pow(1.07,depth-1)*(1+cycle*.2),kindScale=role==='boss'?2:role==='elite'?1.45:1,riskScale=risk?1.18:1;return {name:dungeonDefs[d.dungeon].name,dungeonId:d.dungeon,difficultyTier:tier.level,enemy:d.enemy,icon:'⚔',sprite:d.sprite,encounterId:id,profile:d.profile,secondary:dungeonBossSecondary(d),type:role,depth,risk,waves:depth<4?1:d.waves,balanceVersion:DUNGEON_BALANCE_VERSION,hp:Math.round(80*floorScale*kindScale*diff.hp*d.hpFactor*p.hp*riskScale*tier.hp),damage:Math.round((10+(depth-1)*.65)*(role==='boss'?1.5:role==='elite'?1.25:1)*diff.damage*d.damageFactor*p.damage*(risk?1.1:1)*tier.damage),cd:Math.max(.95,(p.cd*.9-Math.min(.8,(depth-1)*.016))/tier.rate),gold:goldReward(role,depth,risk,d.dungeon),rewardQuality:role==='boss'||role==='elite'||risk}}

function populateAct(dungeonId){const dungeon=dungeonDefs[dungeonId],begin=actIndex()*10;for(let n=0;n<10;n++){const idx=begin+n,type=FLOOR_TYPES[n];if(['combat','elite','boss'].includes(type)){const eligible=dungeon.encounters.map(id=>encounterDefs[id]).filter(e=>e.role===type);ROOMS[idx]=scaledRoom(pick(eligible).id,idx+1,false,type)}else ROOMS[idx]={name:type==='rest'?'A quiet refuge':type==='shop'?'The wandering trader':'A forgotten shrine',enemy:type==='rest'?'Rest and recover':type==='shop'?'Supplies for the descent':'A choice awaits',icon:type==='rest'?'🌿':type==='shop'?'🧳':'✦',hp:0,damage:0,cd:3,type,depth:idx+1,dungeonId}}if(begin===0)ROOMS[begin+2].eventId='provisioner';ROOMS[begin+8].eventId='enchanter';for(let n=0;n<10;n++){if(ROOMS[begin+n].type==='event')decorateEventRoom(ROOMS[begin+n]);else if(ROOMS[begin+n].type==='shop')decorateShopRoom(ROOMS[begin+n])}s.dungeons[actIndex()]=dungeonId;s.route=ROOMS;ensureActMap()}
function preparePortal(){s.phase='portal';s.portalChoices=pickDungeonPortals();save();showPortal()}
function showPortal(){modal('Choose your next dungeon',`Act ${actIndex()+1} · ${difficulty().name} · Depth ${s.room+1}. Choose the dungeon tier you are ready for. Higher tiers are tougher and pay more gold.`,`<div class="choices">${s.portalChoices.map(id=>{const d=dungeonDefs[id];return `<button class="choice portal-choice" onclick="selectPortal('${id}')">${spriteMarkup(d.sprite,d.name,'portalpixel')}<b>${esc(d.name)}</b>${dungeonDifficultyBadge(d.id)}<small>${d.encounters.length} encounter configurations</small><p>${esc(ENCOUNTERS.profiles[d.profile].description)}</p><small>Boss at depth ${(actIndex()+1)*10} · Gold ×${dungeonRating(d.id).gold.toFixed(2)}</small></button>`}).join('')}</div><details class="dungeon-marker-legend"><summary>How dungeon difficulty works</summary><p>1 Beginner · 2 Standard · 3 Advanced · 4 Exaltation · 5 Apex Exalt. Dungeon tiers are RealmPack adaptations, not official RotMG /10 ratings. Compare tiers at the same depth and run mode. Higher tiers increase enemy health, damage, attack rate and gold. Bosses and dangerous paths add further risk.</p></details>`,'portal')}
function selectPortal(id){if(s.phase!=='portal'||!s.portalChoices.includes(id))return;populateAct(id);s.phase='prep';closeModal(true);setEnemy();render();save();toast(dungeonDefs[id].name+' · Build for the enemies ahead.')}
function freshRun(classId='wizard',practice=false){inspected=null;effectHover=null;inventoryCancel();clearInterval(timer);const c=classes[classId];if(!c)throw Error('Unknown class');s={version:4,classId,practice,difficulty:selectedDifficulty,hp:c.hp,max:c.hp,mana:5,block:0,gold:0,room:0,phase:'prep',time:0,seed:(Date.now()>>>0)||1,items:[],stash:[],progress:0,kenseiTime:0,power:0,haste:0,thorns:0,dodge:0,summons:[],enemy:null,bought:[],dungeons:[],portalChoices:[],pathChoices:[],boons:[],relicPower:0,relicHaste:0,kills:0,bosses:0,route:emptyRoute(),history:[]};ROOMS=s.route;uid=0;for(const type of c.startingIds.slice(0,3)){const i=makeItem(type);if(!autoPlace(i))s.stash.push(i)}for(const name of ['Ring of Magic','Health Potion'])if(DATA.byName[name]){const i=makeItem(DATA.byName[name]);if(!autoPlace(i))s.stash.push(i)}if(DATA.byName['Healing Tome'])s.stash.push(makeItem(DATA.byName['Healing Tome']));selected=s.items[0]?.id;logs=[];setEnemy();closeModal(true);log(c.name+' begins the Realm Descent on '+difficulty().name+'.');render();preparePortal()}
function setEnemy(){const r=ROOMS[s.room];s.enemy={hp:r.hp,max:r.hp,damage:r.damage||0,cd:r.cd||3,charge:0,burn:0,poison:0,poisonTime:0,bleed:0,bleedTime:0,chill:0,weaken:0,vulnerable:0,ward:0,wave:1,attacks:0,phaseTwo:false,mechanicTime:0,veil:0};s.block=0;s.time=0;s.progress=0;s.kenseiTime=0;s.power=s.relicPower||0;s.haste=0;s.thorns=0;s.dodge=0;s.summons=[];s.dodgedLastAttack=false;s.venom=0;s.venomTime=0;s.silence=0;s.slow=0;s.items.forEach(i=>{i.charge=0;i.activations=0;i.used=false;i.usesSpent=0;i.hasteRemaining=0});resetItemMechanics();resetClassEffects();setupWave()}
function setupWave(){const r=ROOMS[s.room],e=s.enemy;if(r.waves>1){e.max=Math.round(r.hp*.62);e.hp=e.max}e.charge=0;e.attacks=0;e.ward=['bulwark','reflector'].includes(r.profile)?Math.round(e.max*(r.profile==='bulwark'?.15:.1)):0;e.mechanicTime=0;e.phaseTwo=false;e.veil=0}
function save(){if(!s||s.phase==='fight')return;try{localStorage.setItem('realmpack-v4',JSON.stringify({s,uid,reward,stock}))}catch{}}
function hit(amount){const e=s.enemy,raw=Math.max(0,Math.round(amount*(e.vulnerable>0?1.25:1)*(e.veil>0?.6:1))),absorbed=Math.min(e.ward||0,raw);e.ward=Math.max(0,(e.ward||0)-absorbed);if(absorbed>0&&!e.ward&&ROOMS[s.room].profile==='reflector')e.vulnerable=Math.max(4,e.vulnerable);e.hp=Math.max(0,e.hp-(raw-absorbed));return raw-absorbed}
function gainBlock(amount){s.block=Math.min(Math.round(s.max*.6),s.block+amount)}
function restore(amount,trigger=true){if(s.phase==='fight')amount=Math.round(amount*Math.max(.5,1-Math.max(0,s.time-20)*.02));const actual=Math.min(Math.max(0,amount),s.max-s.hp);s.hp+=actual;if(actual>0)s.realmLastHeal=s.time;if(actual>0&&s.venom>0)s.venom=Math.max(0,s.venom-1);if(trigger)passive('heal',actual);itemEvent('heal',actual);return actual}
function cooldown(i){const d=defs[i.type],q=d.kind==='bow'?s.items.filter(j=>defs[j.type].kind==='quiver'&&adjacent(i,j)).length:0;const result=daggerCooldown(i,d.cd)*(affinityCooldown(d)/d.cd)*(1-Math.min(.2,i.eventHaste||0))*enchantCooldown(i)*(s.slow>0?1.2:1)/(1+daggerHasteRate(i)+Math.min(.6,q*.15)+(s.relicHaste||0)+adjacencyStat(i,'rate')+realmSetRate(i));return Math.max(d.mechanic?.rampFloor||0,result)}
function enemyProfiles(){const r=ROOMS[s.room];return r.type==='boss'&&s.enemy.phaseTwo?[r.profile,r.secondary].filter(Boolean):[r.profile]}
function playerDamage(amount,pierce=0,canDodge=true){if(s.hp<=0)return;const e=s.enemy;if(canDodge&&s.time<(s.daggerInvulnerableUntil||0)){log('✦ Heartguard prevents an attack.');return false}if(canDodge&&s.time<(s.realmDivineUntil||0)){s.realmDivineUntil=0;log('✦ Borrowed divinity prevents an attack.');return false}if(canDodge&&s.dodge>0&&!s.dodgedLastAttack){s.dodgedLastAttack=true;s.dodge--;passive('dodge',1);log('You dodge '+ROOMS[s.room].enemy+'’s attack.');return false}s.dodgedLastAttack=false;pierce=Math.max(pierce,ROOMS[s.room].type==='boss'?.15:ROOMS[s.room].type==='elite'?.08:0);const damage=Math.max(0,Math.round(amount*(e.weaken>0?.75:1)*(s.time<(s.realmArmoredUntil||0)?.8:1))),unblockable=Math.round(damage*pierce),blocked=Math.min(s.block,damage-unblockable);s.block-=blocked;const dealt=damage-blocked;s.hp=Math.max(0,s.hp-dealt);itemEvent('hurt',dealt);passive('block',blocked);itemEvent('block',blocked);log(ROOMS[s.room].enemy+': '+dealt+' damage, '+blocked+' blocked.');if(enemyProfiles().includes('vampire'))e.hp=Math.min(e.max,e.hp+Math.round(dealt*.4));flash('playerSprite');return true}
function enemyAttack(){const e=s.enemy,profiles=enemyProfiles();e.attacks++;const ramp=Math.max(0,Math.floor((s.time-30)/10)+1)*5;let amount=e.damage+ramp;if(profiles.includes('raider')&&e.attacks%3===0)amount*=1.5;if(profiles.includes('berserker')&&e.hp<=e.max/2)amount*=1.25;const connected=playerDamage(amount);if(s.hp<=0)return;if(connected&&profiles.includes('venom')){s.venom=Math.min(12,s.venom+1);s.venomTime=5;log('Venom applied. Healing reduces its stacks.')}if(profiles.includes('hexer')&&e.attacks%3===0&&s.time-(e.lastHexAt??-7)>=7){e.lastHexAt=s.time;s.mana=Math.max(0,s.mana-3);s.silence=Math.max(3,s.silence);log('Hex: mana drained and silence applied.')}if(connected&&profiles.includes('frostbinder')&&e.attacks%3===0){s.slow=Math.max(4,s.slow);log('Frost slows your backpack.')}if(profiles.includes('duelist')&&e.attacks%4===0){log('Double strike!');playerDamage(amount)}if(s.thorns>0)hit(s.thorns)}
function encounterSecond(){const e=s.enemy,profiles=enemyProfiles();e.mechanicTime++;if(s.venom>0&&s.venomTime>0){s.hp=Math.max(0,s.hp-s.venom);log('Venom deals '+s.venom+' damage.')}for(const profile of profiles){switch(profile){case'mender':e.hp=Math.min(e.max,e.hp+Math.max(1,Math.round(e.max*.02*(e.burn+e.poison>0?.5:1))));break;case'shaman':if(e.mechanicTime%8===0){e.hp=Math.min(e.max,e.hp+Math.round(e.max*.07));e.burn=Math.max(0,e.burn-1);e.poison=Math.max(0,e.poison-1);log('Shaman heals and cleanses afflictions.')}break;case'bulwark':if(e.mechanicTime%10===0){e.ward=Math.min(e.max*.3,e.ward+Math.round(e.max*.1));log('Enemy ward restored.')}break;case'arcanist':if(e.mechanicTime%7===0){log('Arcane pulse!');playerDamage(e.damage*.65,.5)}break;case'tidecaller':if(e.mechanicTime%8===0){s.block=Math.floor(s.block*.75);log('Tidal wave!');playerDamage(e.damage*.65)}break;case'parasite':if(e.mechanicTime%6===0){s.mana=Math.max(0,s.mana-2);e.ward=Math.min(e.max*.3,e.ward+Math.round(e.max*.05));log('Parasite drains mana and grows a ward.')}break;case'trickster':if(e.mechanicTime%8===0){e.veil=2;log('Illusion veil reduces damage for 2 seconds.')}break;case'suppressor':if(e.mechanicTime%7===0){s.silence=3;log('Suppression: your equipment is silenced.')}break;case'artillerist':if(e.mechanicTime%6===0){log('Artillery shell!');playerDamage(e.damage*.75)}break}}}
function startFight(){if(s.phase!=='prep')return;const r=ROOMS[s.room];if(r.type==='rest')return enterRest();if(r.type==='shop')return enterShop();if(r.type==='event')return enterEvent();if(s.stash.length>STASH_LIMIT)return toast('Stash exceeds 9 slots. Equip, sell or discard the excess before battle.');if(!s.items.some(i=>['damage','drain','poison','burn','bleed','summon'].includes(defs[i.type].effect)))return toast('Pack a damage source first.');setEnemy();s.mana=Math.max(5,s.mana);applyEventBuffs();startEnchantments();s.phase='fight';closeModal(true);log('Depth '+(s.room+1)+': '+r.enemy+' — '+ENCOUNTERS.profiles[r.profile].name+'.');render();timer=setInterval(()=>tick(.05*speed),50)}
function tick(dt){if(s.phase!=='fight'||catalogueOpen||bestiaryOpen||(modalKind==='help'||modalKind==='runmap'))return;const e=s.enemy,previous=Math.floor(s.time),r=ROOMS[s.room];s.time+=dt;tickItemMechanics(dt);tickClassEffects(dt);s.haste=Math.max(0,s.haste-dt);for(const i of s.items)i.hasteRemaining=Math.max(0,(i.hasteRemaining||0)-dt);s.silence=Math.max(0,s.silence-dt);s.slow=Math.max(0,s.slow-dt);s.venomTime=Math.max(0,s.venomTime-dt);if(!s.venomTime)s.venom=0;e.veil=Math.max(0,e.veil-dt);for(const key of ['chill','weaken','vulnerable','poisonTime','bleedTime'])e[key]=Math.max(0,e[key]-dt);if(!e.poisonTime)e.poison=0;if(!e.bleedTime)e.bleed=0;passive('time',dt);if(s.classId==='kensei'){s.kenseiTime+=dt;if(s.kenseiTime>=8){s.kenseiTime-=8;s.dodge=Math.min(3,s.dodge+1)}}for(const pet of s.summons)pet.duration-=dt;s.summons=s.summons.filter(p=>p.duration>0);if(r.type==='boss'&&!e.phaseTwo&&e.hp<=e.max/2){e.phaseTwo=true;e.damage=Math.round(e.damage*1.2);log('BOSS PHASE II: '+(r.secondary?ENCOUNTERS.profiles[r.secondary].name:'Enraged')+' joins the battle pattern!');flash('enemySprite')}
if(Math.floor(s.time)>previous){s.block=Math.max(0,Math.floor(s.block*.9));if(!s.silence)s.mana=Math.min(50,s.mana+1);const status=e.burn+e.poison+e.bleed;if(status){hit(Math.round(status*(r.type==='boss'?.7:r.type==='elite'?.85:1)));e.burn=Math.max(0,e.burn-1);e.poison=Math.max(0,e.poison-1);e.bleed=Math.max(0,e.bleed-1);log('Afflictions deal '+status+' damage.')}if(s.summons.length){const amount=s.summons.reduce((a,p)=>a+p.power,0);hit(amount);log('Companions deal '+amount+' damage.')}if(e.hp>0)encounterSecond()}
if(s.hp>0)for(const i of s.items){if(e.hp<=0)break;if(s.silence&&defs[i.type].mechanic?.key!=='purify'&&!defs[i.type].mechanic?.cleanse)continue;if(i.used)continue;i.charge=Math.min(cooldown(i),i.charge+dt);if(i.charge+1e-8>=cooldown(i))activate(i)}if(s.hp<=0||s.time>=150)return finishBattle(false);if(e.hp<=0)return finishBattle(true);let rate=e.chill>0?1/1.35:1;if(enemyProfiles().includes('berserker')&&e.hp<e.max/2)rate*=1.25;e.charge+=dt*rate;if(e.charge>=e.cd){e.charge-=e.cd;enemyAttack()}updateStats();if(s.hp<=0)return finishBattle(false);if(e.hp<=0)return finishBattle(true)}
function finishBattle(victory){if(!victory&&tryItemRescue())return;const r=ROOMS[s.room];if(victory)daggerEnemyDefeated();if(victory&&s.enemy.wave<(r.waves||1)){s.enemy.wave++;s.enemy.hp=s.enemy.max;setupWave();log('Wave '+s.enemy.wave+' / '+r.waves+' approaches.');updateStats();return}clearInterval(timer);if(victory){s.kills++;s.gold+=r.gold??14;if(r.type==='boss')s.bosses++;s.history.push({depth:s.room+1,encounter:r.encounterId,victory:true});log('Victory! +'+(r.gold??14)+' gold.');s.phase='reward';reward=rollLoot(r.type==='boss'?4:3);render();save();showRewards()}else{s.history.push({depth:s.room+1,encounter:r.encounterId,victory:false});s.phase='lost';render();save();showEnding()}}
const SHINY_RATES={combat:1/500,elite:1/250,boss:1/100};
function shinyUpgrade(id,role,random=rng){const d=defs[id],variants=DATA.shinyByBase[id];if(!d||d.isShiny||!variants?.length)return id;const chance=SHINY_RATES[role]||0;if(!chance||random()>=chance)return id;return variants[Math.min(variants.length-1,Math.floor(random()*variants.length))]}
function lootRarityWeights(role,act){const base=act<=0?[.60,.32,.075,.005]:act===1?[.15,.55,.27,.03]:[.02,.28,.55,.15];if(role==='boss')return act<=0?[.02,.23,.60,.15]:[0,.05,.55,.40];if(role==='elite')return act<=0?[.08,.47,.40,.05]:[0,.15,.60,.25];return base}
function rollLoot(n,context='drop'){if(context==='shop')return rollSpecialistStock(n,currentShopSpecialist()?.kind||ROOMS[s.room].shopKind||chooseShopKind());const c=classes[s.classId],r=ROOMS[s.room],role=context==='shop'?'shop':r.risk?'elite':r.type,weights=lootRarityWeights(role,actIndex()),eligible=DATA.items.filter(d=>!d.isShiny&&!d.lootExcluded),chosen=[],used=new Set();for(let slot=0;slot<n;slot++){let roll=rng(),quality=3;for(let q=0;q<weights.length;q++){roll-=weights[q];if(roll<0){quality=q;break}}let pool=eligible.filter(d=>d.quality===quality&&!used.has(d.id));if(!pool.length)pool=eligible.filter(d=>!used.has(d.id));if(!pool.length)break;let total=pool.reduce((sum,d)=>sum+(d.classes.includes(c.id)?3:1),0),target=rng()*total,picked=pool[pool.length-1];for(const d of pool){target-=d.classes.includes(c.id)?3:1;if(target<0){picked=d;break}}used.add(picked.id);chosen.push(context==='shop'?picked.id:shinyUpgrade(picked.id,r.type))}return chosen}

function shinyInfo(d){if(d.daggerUnavailable)return '<p class="effect-note">Temporarily unobtainable. Existing saved copies remain usable.</p>';if(!d.isShiny)return '';const base=defs[d.baseId];return `<div class="shiny-note"><b>✦ SHINY VARIANT</b><p>Special version of ${esc(base.name)}. ${d.daggerUpdate?'Same size and identity, with stronger primary/signature values and a faster cooldown.':'Same size, mana cost, effects and synergies, with a faster cooldown.'} Compare its primary effect below.</p><small>Regular → Shiny: ${base.cd}s → ${d.cd}s · ${base.amount} → ${d.amount} ${esc(d.effect)}</small><p>Eligible reward upgrade chance: 1/500 normal · 1/250 elite · 1/100 boss. Drop-only in normal runs.</p></div>`}

function takeLoot(id){if(s.phase!=='reward'||id&&!reward.includes(id))return;if(id){if(!daggerAvailable(id))return toast('This item is currently unavailable.');if(!receiveItem(makeItem(id)))return;log('Acquired '+defs[id].name+'.')}else restore(Math.max(6,Math.round(s.max*.06)),false);if(ROOMS[s.room].type==='boss'){s.phase='boon';save();showBoon()}else nextRoom()}
function showBoon(){modal('Claim a boss blessing','Every boss grants a permanent benefit for this run. Each blessing also restores 15% of your maximum health.',`<div class="choices"><button class="choice" onclick="takeBoon('power')"><b>⚔ Oryx’s Might</b><p>Start every battle with +2 damage power.</p></button><button class="choice" onclick="takeBoon('haste')"><b>✧ Crystal Tempo</b><p>Your entire backpack recharges 6% faster (stacks to 48%).</p></button><button class="choice" onclick="takeBoon('life')"><b>♡ Ancient Vitality</b><p>Gain 12 maximum health and restore 12 additional health.</p></button></div>`,'boon')}
function takeBoon(choice){if(s.phase!=='boon'||!['power','haste','life'].includes(choice))return;if(choice==='power')s.relicPower+=2;else if(choice==='haste')s.relicHaste=Math.min(.48,(s.relicHaste||0)+.06);else{s.max+=12;s.hp+=12}s.boons.push(choice);restore(Math.round(s.max*.15),false);nextRoom()}
function nextRoom(){selected=null;reward=[];stock=[];s.room++;if(s.room>=ROOMS.length){s.room=ROOMS.length-1;s.phase='won';render();save();showEnding();return}s.phase='prep';closeModal(true);if(s.room%10===0){setEnemy();render();preparePortal();return}if(ROOMS[s.room].type==='combat'){preparePath();return}setEnemy();render();save()}
function preparePath(){ensureActMap();s.pathChoices=s.mapBranches[s.room]||[ROOMS[s.room]];s.phase='path';save();showPath()}
function showPath(){modal('Choose your path',`Depth ${s.room+1} · ${dungeonDefs[s.dungeons[actIndex()]].name}. Preview the threat before committing.`,`<div class="map-dungeon-rating">${dungeonDifficultyBadge(s.dungeons[actIndex()])}</div><button onclick="showRunMap()">View branching map ↗</button><div class="choices">${s.pathChoices.map((r,n)=>`<button class="choice" onclick="selectPath(${n})">${r.type==='event'?`<div class="event-path-icon">${eventScene(r.eventId,'path')}</div><b>${esc(r.name)}</b><small>Non-combat encounter</small><p>${esc(noncombatById[r.eventId].desc)}</p><strong>Trades, risks, and run rewards</strong>`:`${spriteMarkup(r.sprite,r.enemy,'portalpixel')}<b>${n?'Dangerous passage':'Steady passage'}</b><small>${esc(r.enemy)} · ${r.hp} HP · ${r.damage} damage</small><p>${esc(ENCOUNTERS.profiles[r.profile].description)}</p><strong>${r.gold} gold${n?' · better odds of rare loot':''}</strong>`}</button>`).join('')}</div>`,'path')}
function selectPath(n){if(s.phase!=='path'||!s.pathChoices[n])return;s.mapTaken=s.mapTaken||{};s.mapTaken[s.room]=n;ROOMS[s.room]=s.pathChoices[n];s.route=ROOMS;s.phase='prep';closeModal(true);setEnemy();render();save()}
function resolveRest(choice){if(s.phase!=='rest')return;if(choice==='heal')restore(Math.round(s.max*.3),false);else if(choice==='max'){s.max+=10;s.hp+=10}else return;nextRoom()}
function showRest(){modal('A quiet refuge','Prepare for the chambers ahead. Health persists through the descent.',`${eventScene('rest')}<div class="choices"><button class="choice" onclick="resolveRest('heal')"><b>Rest by the fire</b><p>Restore ${Math.round(s.max*.3)} health (30% of maximum).</p></button><button class="choice" onclick="resolveRest('max')"><b>Train your resolve</b><p>Gain 10 maximum health and restore 10 health.</p></button></div>`,'rest')}
function continueEndless(){if(s.phase!=='won')return;const start=ROOMS.length;ROOMS.push(...emptyRoute(start));s.route=ROOMS;s.room=start;s.phase='prep';s.hp=s.max;setEnemy();closeModal(true);render();preparePortal()}
function showEnding(){const won=s.phase==='won';modal(won?'The descent is conquered.':'The realm claims another.',`${classes[s.classId].name} · ${difficulty().name} · Depth ${s.room+1} · ${s.kills} victories · ${s.bosses} bosses`, `<p>${won?'Your three-act expedition is complete. Venture into another three acts with stronger enemies, or begin a fresh build.':'Every descent draws from 350 encounter configurations across 35 dungeon themes. Try a different path, class, or build.'}</p>${won?'<button class="gold" onclick="continueEndless()">Continue into endless descent ↗</button> ':''}<button onclick="chooseClass()">Choose a new adventurer</button>`,'ending')}
function restorePhaseModal(){if(s.phase==='reward')showRewards();else if(s.phase==='rest')showRest();else if(s.phase==='shop')showShop();else if(s.phase==='portal')showPortal();else if(s.phase==='path')showPath();else if(s.phase==='event')showEvent();else if(s.phase==='eventResult')showEventResult();else if(s.phase==='boon')showBoon();else if(['won','lost'].includes(s.phase))showEnding();else closeModal(true)}
function closeModal(force=false){if(!force&&['reward','rest','shop','portal','path','event','eventResult','boon','won','lost'].includes(s?.phase))return restorePhaseModal();catalogueOpen=false;bestiaryOpen=false;modalKind='';if(!window.__TEST__)$('overlay').innerHTML=''}
function chooseClass(practice=false){if(s?.phase==='fight')return;catalogueOpen=false;bestiaryOpen=false;modal('Choose your adventurer',`19 classes · 35 dungeons · 350 encounters · Three acts, then endless descent`, `<div class="class-switch"><button class="${!practice?'gold':''}" onclick="chooseClass(false)">Dungeon run</button><button class="${practice?'gold':''}" onclick="chooseClass(true)">Sandbox</button><select aria-label="Starting difficulty" onchange="selectedDifficulty=this.value">${Object.entries(DIFFICULTIES).map(([id,d])=>`<option value="${id}" ${id===selectedDifficulty?'selected':''}>${d.name} · ${d.hp}× enemy health</option>`).join('')}</select>${s?'<button onclick="closeModal()">Return to current run</button>':''}</div><p class="muted">Choose a portal each act. Enemies scale with depth; elites and bosses grant greater rewards. Select a difficulty above, then a class.</p><div class="class-grid">${Object.values(classes).map(c=>`<button class="class-card" onclick="freshRun('${c.id}',${practice})">${spriteMarkup(c.sprite,c.name,'classpixel')}<div><h2>${c.name}</h2><small>${c.hp} health · ${esc(defs[c.startingIds[0]]?.kind||'')}</small></div><p>${esc(c.desc)}</p><strong>${esc(c.title)}</strong><p class="class-rule">${esc(c.rule)}</p></button>`).join('')}</div>`,'classes')}
function openBestiary(){bestiaryOpen=true;bestiaryPage=0;drawBestiary()}
function drawBestiary(){const query=bestiarySearch.toLowerCase(),all=ENCOUNTERS.encounters.filter(d=>(d.name+' '+dungeonDefs[d.dungeon].name+' '+d.profile+' '+d.role).toLowerCase().includes(query)),pages=Math.max(1,Math.ceil(all.length/18));bestiaryPage=Math.min(bestiaryPage,pages-1);modal('The realm bestiary','350 encounter configurations · 35 dungeon themes · 18 mechanical profiles. Names and sprites from realm.wiki; combat patterns are custom adaptations.',`<div class="catalogue-controls"><input id="bestiarySearch" placeholder="Search enemies, dungeons, profiles…" aria-label="Search encounters" value="${esc(bestiarySearch)}" oninput="filterBestiary(this.value)"><button onclick="closeBestiary()">Close ✕</button></div><div class="catalogue-grid">${all.slice(bestiaryPage*18,bestiaryPage*18+18).map(d=>`<article class="codex-card ${d.isShiny?'shiny':''}"><div class="codex-top">${spriteMarkup(d.sprite,d.enemy,'itempixel')}<div><h3>${esc(d.enemy)}</h3><small>${esc(dungeonDefs[d.dungeon].name)} · ${d.role}</small></div></div>${dungeonDifficultyBadge(d.dungeon)}<p>${esc(ENCOUNTERS.profiles[d.profile].description)}</p>${d.role==='boss'?`<p class="synergy">Phase II: ${esc(dungeonSecondaryText(d))}</p>`:''}<small>${d.waves} wave${d.waves>1?'s':''} · stats scale to depth and difficulty</small><div class="codex-bottom"><a href="${d.source}" target="_blank" rel="noopener">Wiki ↗</a>${s?.practice?`<button ${s.phase!=='prep'?'disabled':''} onclick="loadPracticeEncounter('${d.id}')">Try encounter</button>`:''}</div></article>`).join('')}</div><div class="pagination"><button ${!bestiaryPage?'disabled':''} onclick="bestiaryPage--;drawBestiary()">← Previous</button><small>${all.length} encounters · Page ${bestiaryPage+1} / ${pages}</small><button ${bestiaryPage>=pages-1?'disabled':''} onclick="bestiaryPage++;drawBestiary()">Next →</button></div>`,'catalogue')}
function filterBestiary(value){bestiarySearch=value;bestiaryPage=0;drawBestiary();const e=$('bestiarySearch');e.focus();e.setSelectionRange(e.value.length,e.value.length)}
function closeBestiary(){bestiaryOpen=false;restorePhaseModal()}
function loadPracticeEncounter(id){if(!s.practice||s.phase!=='prep'||!encounterDefs[id])return;ROOMS[s.room]=scaledRoom(id,s.room+1);s.route=ROOMS;setEnemy();bestiaryOpen=false;closeModal(true);render();save()}
function updateExpeditionUI(){if(window.__TEST__||!s)return;const r=ROOMS[s.room],c=classes[s.classId],e=s.enemy;setStableHTML('dungeonDifficulty',dungeonDifficultyBadge(dungeonIdForRoom(r)));const begin=Math.floor(s.room/10)*10;setStableHTML('route',runMapMarkup());$('routeCount').textContent='ACT '+(actIndex()+1);$('runEyebrow').textContent=`REALM DESCENT · ACT ${actIndex()+1} · ${difficulty().name.toUpperCase()}`;$('roomtype').textContent=`DEPTH ${s.room+1} · ${r.type.toUpperCase()}`;$('roomtitle').textContent=r.name;renderRoomArtwork(r);setStableHTML('encounterInfo',r.encounterId?`<div><b>${esc(ENCOUNTERS.profiles[r.profile].name)}</b> · ${esc(ENCOUNTERS.profiles[r.profile].description)}</div>${r.type==='boss'?`<div class="synergy">Phase II: ${esc(dungeonSecondaryText(r))}</div>`:''}<div class="encounter-meta">${r.waves||1} wave${r.waves>1?'s':''} · ${r.gold} gold · ${r.risk?'Dangerous passage · ':''}${difficulty().name} · enemy strength scales with depth · Block: 60% HP cap, 10% decay/s · No consecutive dodges${r.type==='boss'?' · Boss: 15% piercing strikes, 30% affliction resistance':r.type==='elite'?' · Elite: 8% piercing strikes, 15% affliction resistance':''}</div>`:'<div>A moment to plan your next step in the descent.</div>');$('runSummary').textContent=`${s.eventBuffs&&Object.keys(s.eventBuffs).length?'Blessing ready · ':''}${s.kills} victories · ${s.bosses} bosses · ${s.boons.length} blessings`;$('estats').textContent=e.max?`${Math.ceil(e.hp)} / ${e.max} HP${e.ward>0?' + '+Math.ceil(e.ward)+' ward':''} · ${e.damage} dmg / ${e.cd.toFixed(1)}s · wave ${e.wave} / ${r.waves||1}${e.phaseTwo?' · PHASE II':''}`:'A moment of respite';if(s.silence>0)$('effects').textContent+=' · ✕ silenced';if(s.venom>0)$('effects').textContent+=' · ☠ '+s.venom+' venom';if(s.slow>0)$('effects').textContent+=' · ❄ slowed';if(e.veil>0)$('effects').textContent+=' · ◇ enemy veil';if(s.phase==='fight'&&s.time>20)$('effects').textContent+=' · healing '+Math.round(Math.max(.5,1-(s.time-20)*.02)*100)+'%';if(s.phase==='fight'&&s.time>=30)$('effects').textContent+=' · ENRAGED'}
function rebalanceSavedRoute(){migrateDungeonBalance();for(let i=s.room+1;i<ROOMS.length;i++)if(ROOMS[i].type==='rest'&&i%10===8)ROOMS[i]=decorateEventRoom({name:'',enemy:'A choice awaits',icon:'✦',hp:0,damage:0,cd:3,type:'event',depth:i+1,dungeonId:ROOMS[i].dungeonId});for(let i=s.room+1;i<ROOMS.length;i++)if(i%10===8&&ROOMS[i].type==='event')ROOMS[i]=decorateEventRoom({...ROOMS[i],eventId:'enchanter'});s.route=ROOMS;if(s.phase==='prep')setEnemy()}

function boot(){document.addEventListener('keydown',e=>{if(e.target.matches?.('input,select,textarea'))return;if(e.key.toLowerCase()==='r'&&!e.ctrlKey&&!e.metaKey&&!modalKind)rotateSelected();if(e.key==='Escape'){if(bestiaryOpen)closeBestiary();else if(catalogueOpen)closeCatalogue();else if(modalKind)closeModal();else{selected=null;render()}}});try{const saved=JSON.parse(localStorage.getItem('realmpack-v4'));if(saved?.s?.version===4&&classes[saved.s.classId]&&Array.isArray(saved.s.route)&&saved.s.room>=0&&saved.s.room<saved.s.route.length&&[...saved.s.items,...saved.s.stash].every(i=>defs[i.type])){s=saved.s;ROOMS=s.route;uid=saved.uid;stock=saved.stock||[];reward=saved.reward||[];selectedDifficulty=s.difficulty;migrateDaggerItems();rebalanceSavedRoute();refreshEncounterArtwork();rebalanceGold();if(s.phase==='fight'){s.phase='prep';setEnemy()}render();log('Your expedition continues at depth '+(s.room+1)+'.');restorePhaseModal();return}const legacy=JSON.parse(localStorage.getItem('realmpack-v3'));if(legacy?.s&&classes[legacy.s.classId]&&[...legacy.s.items,...legacy.s.stash].every(i=>defs[i.type])){const old=legacy.s;freshRun(old.classId,old.practice);s.items=old.items;s.stash=old.stash;s.gold=old.gold;s.max=old.max;s.hp=Math.max(old.hp,Math.round(old.max*.5));uid=legacy.uid;migrateDaggerItems();save();render();toast('Your previous backpack has been carried into the expanded descent.');return}}catch{}freshRun('wizard');chooseClass()}

if(!window.__TEST__)boot();
